'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'未提供':Math.abs(Number(n))>0&&Math.abs(Number(n))<.0001?Number(n).toExponential(4):Number(n).toLocaleString('zh-CN',{maximumSignificantDigits:7});
const chem=s=>esc(s).replace(/(\d+)/g,'<sub>$1</sub>');
const sourceName=s=>({'SciGlass':'SciGlass 国际玻璃库','New Glass Forum':'New Glass Forum 实验表','OHARA':'OHARA 小原','SCHOTT':'SCHOTT 肖特','HOYA':'HOYA 豪雅','Matbench':'Matbench 金属玻璃','BIMOG':'BIMOG 有机玻璃'}[s]||s);
const originName=s=>({'原表解析':'实验原表','原始实验表':'实验原表','性质汇总':'数据库汇总'}[s]||s);
const basisName=s=>({'mol%':'摩尔百分比','wt%':'质量百分比','at%':'原子百分比','质量配比':'质量配比','分子式':'分子式','未公开完整配方':'完整组分未公开'}[s]||s);
const unitText=s=>s==='1'?'无量纲':s==='目录原表'?'单位见原目录':s||'单位未提供';
let components=[],system='',view='systems',offset=0,total=0,limit=18,seq=0,detailSeq=0,current=null,propOffset=0,propertySeq=0,sortBy='property_count',sortOrder='desc';
let summary=null,selected=new Map(),points=new Map();
async function get(url){const r=await fetch(url);if(!r.ok){let message;try{message=(await r.json()).detail}catch{}throw new Error(message||`数据读取失败（${r.status}）`)}return r.json()}
function error(e){$('error').hidden=false;$('error').textContent=e.message||String(e)}
function readSort(){const raw=(($('sortBy')||{}).value||'property_count:desc').split(':');sortBy=raw[0]||'property_count';sortOrder=raw[1]||'desc'}
function params(){readSort();const p=new URLSearchParams({q:$('query').value,components:components.join(','),match:$('match').value,system,view,offset,limit,pcb:$('pcb').checked,source:$('source').value,family:$('family').value,sort:sortBy,order:sortOrder});if($('kind').value){const[kind,unit]=JSON.parse($('kind').value);p.set('kind',kind);p.set('unit',unit)}for(const k of ['lo','hi'])if($(k).value!=='')p.set(k,$(k).value);return p}
function chips(){$('chips').innerHTML=components.map((x,i)=>`<button data-chip="${i}" aria-label="移除${esc(x)}">${chem(x)} ×</button>`).join('')}
function add(x){if(x&&!components.includes(x)){components.push(x);chips()}}
function compositionText(c){return Object.entries(c||{}).filter(([k,v])=>v!==null&&v!==''&&v!=='-'&&Number(v)!==0).map(([k,v])=>`${k} ${formatAmount(v)}`).join(' · ')}
function formatAmount(v){if(v==null||v===''||v==='-')return '未提供';const n=Number(v);return Number.isFinite(n)?fmt(n):String(v)}
function basisShort(b){return {'mol%':'mol%','wt%':'wt%','at%':'at%','质量配比':'质量比'}[b]||''}
function highlightNames(){return new Set(components)}
function compositionSummary(comp,basis,limit){const hits=highlightNames();const entries=Object.entries(comp||{}).filter(([k,v])=>v!==null&&v!==''&&v!=='-'&&Number(v)!==0).sort((a,b)=>(Number(b[1])||0)-(Number(a[1])||0));if(!entries.length)return '';const shown=typeof limit==='number'?entries.slice(0,limit):entries;const unit=basisShort(basis);return (unit?`<span class="comp-basis">${esc(basisName(basis))}</span>`:'')+shown.map(([k,v])=>`<span class="comp-token${hits.has(k)?' hit':''}">${chem(k)} <b>${esc(formatAmount(v))}</b>${unit?` <small>${esc(unit)}</small>`:''}</span>`).join('')+(entries.length>shown.length?`<span class="comp-more">另有 ${entries.length-shown.length} 种组分</span>`:'')}
function previewProps(previews,matches){const matchedKinds=new Set((matches||[]).map(p=>p.kind));const extras=(previews||[]).filter(p=>!matchedKinds.has(p.kind));if(!extras.length)return '';storePoints(extras);return `<div class="preview-props">${extras.map(p=>`<span class="preview-prop"><span>${esc(p.kind)}</span><b>${val(p)}</b> <small>${esc(unitText(p.unit))}</small>${conditionButton(p)}</span>`).join('')}</div>`}
function sourceLine(sources){return (sources&&sources.length)?`<div class="source-line">${sources.map(s=>`<span class="pill neutral">${esc(sourceName(s.source))}</span>`).join('')}</div>`:''}
function kindFilterText(){if(!$('kind').value)return '';const[kind,unit]=JSON.parse($('kind').value);const lo=$('lo').value,hi=$('hi').value;const range=[lo!==''?'≥ '+lo:'',hi!==''?'≤ '+hi:''].filter(Boolean).join(' 且 ');return `${kind}${range?' '+range:''}${unit&&unit!=='1'?' '+unit:''}`}
function activeConditions(){const list=[];for(const k of components)list.push('含 '+k);if(typeof excludedIngredients!=='undefined')for(const k of excludedIngredients)list.push('不含 '+k);if(typeof intentFilters!=='undefined')for(const f of intentFilters)list.push(typeof filterText==='function'?filterText(f):f.kind);const kf=kindFilterText();if(kf&&(typeof intentFilters==='undefined'||!$('kind').value||!intentFilters.some(f=>f.kind===JSON.parse($('kind').value)[0]&&f.unit===JSON.parse($('kind').value)[1])))list.push(kf);if($('query').value.trim())list.push('关键词 “'+$('query').value.trim()+'”');if($('source').value)list.push('来源 '+sourceName($('source').value));if($('family').value)list.push('类别 '+$('family').value);if($('pcb').checked)list.push('有PCB用途标注');if($('match').value==='exact'&&components.length)list.push('仅包含所选组分');if(system)list.push('组分组合 '+system);return list}
function emptyState(){const conds=activeConditions();const hint=conds.length?'可取消上方某一条件后重试，或在高级筛选中放宽数值范围。':'可减少组分、放宽数值范围，或切换到“材料列表”按产品型号检索。';return `<div class="no-results"><strong>没有找到同时满足全部条件的材料</strong>${conds.length?`<p>当前已应用的条件：</p><ul class="empty-conditions">${conds.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p>${esc(hint)}${view==='systems'?' 也可切换到“材料列表”按产品型号或关键词检索。':''}</p></div>`}
function opticalName(path){const s=String(path||'').replace(/\\/g,'/');const parts=s.split('/').filter(Boolean);return parts.slice(-3).join(' / ')||'光谱或色散资料'}
async function showOptical(id){try{const d=await get('/api/glass/optical/'+id);const data=d.data||{};const comments=data.COMMENTS||data.comments||'';const refs=data.REFERENCES||data.references||'';const cond=data.CONDITIONS||data.conditions||{};const tables=data.DATA||[];const preview=Array.isArray(tables)?tables.map(t=>{const raw=String(t.data||t.DATA||'').trim();const lines=raw.split(/\n/);return `<div class="optical-block"><p class="hint">${esc(t.type||t.Type||'数据表')}</p><pre>${esc(lines.slice(0,8).join('\n'))}${lines.length>8?'\n…':''}</pre></div>`}).join(''):'';$('conditionContent').innerHTML=`<div class="condition-lead"><h3>光谱 / 色散资料</h3><p class="hint">${esc(d.source_path||'')}</p></div>${comments?`<p>${esc(comments)}</p>`:''}${cond&&Object.keys(cond).length?`<div class="condition-definition"><span>测量条件</span><span>${esc(typeof cond==='object'?JSON.stringify(cond):String(cond))}</span></div>`:''}${refs?`<p class="hint">${esc(typeof refs==='object'?JSON.stringify(refs):String(refs))}</p>`:''}${preview||'<p class="missing">未提供可预览的数值表。</p>'}<p style="margin-top:12px"><a href="/api/glass/optical/${id}" target="_blank" rel="noopener noreferrer">查看完整 JSON 资料 ↗</a></p>`;$('conditionModal').showModal()}catch(e){error(e)}}
function recipeRow(x){const hits=highlightNames();const keys=Object.keys(x.comp||{});const title=x.family==='厂商产品'&&x.name?esc(x.name):keys.length?x.system.split(' / ').slice(0,9).map(k=>`<span class="${hits.has(k)?'hit':''}">${chem(k)}</span>`).join(' / ')+(keys.length>9?' …':''):esc(x.name);const comp=compositionSummary(x.comp,x.basis,4)||'<span class="missing">完整组分未公开</span>';const matches=x.matches||[];const seen=new Set();const key=matches.filter(p=>!seen.has(p.kind)&&seen.add(p.kind));const tg=(x.previews||[]).find(p=>p.kind==='玻璃转变温度');const shown=key.length?key:tg?[tg]:[];const keyHTML=shown.length?shown.map(p=>`<div class="key-prop"><span>${esc(p.kind)}</span><b>${val(p)}</b> <small>${esc(p.unit==='1'?'':unitText(p.unit))}</small></div>`).join(''):'<span class="hint">点开查看性质</span>';return `<tr data-rid="${x.id}"><td><div class="material-name">${title}</div><div class="composition-line">${comp}</div><span class="hint">编号 M${x.id}</span></td><td class="key-cell">${keyHTML}</td><td><button class="view-recipe" data-rid="${x.id}">查看配方 →</button></td></tr>`}
function comparebar(){$('compareText').textContent=selected.size?`已选择 ${selected.size} / 4 条材料`:'选择2至4条配方进行比较';$('compare').disabled=selected.size<2}
async function search(){if(window.revealResults)window.revealResults();const n=++seq;$('error').hidden=true;$('results').style.opacity='.45';$('found').textContent='正在查询本地数据…';try{const d=await get('/api/glass/search?'+params());if(n!==seq)return;total=d.total;$('results').style.opacity='1';$('found').textContent=`共 ${fmt(total)} ${view==='systems'?'种组分组合':'条去重材料条目'}`;$('listTitle').textContent=view==='systems'?'浏览组分组合':system?'该组合下的材料':'材料检索结果';$('viewLabel').textContent=view==='systems'?'组成目录':'配方与产品';$('all').classList.toggle('on',view==='systems');$('listView').classList.toggle('on',view!=='systems');$('breadcrumb').hidden=!system;$('breadcrumb').innerHTML=system?`<span>当前组分组合</span><strong>${system.split(' / ').map(chem).join(' / ')}</strong><button class="text" id="backSystems">返回目录 ×</button>`:'';
if($('sortBy'))$('sortBy').disabled=view==='systems';
if(!d.items.length)$('results').innerHTML=emptyState();
else if(view==='systems')$('results').innerHTML='<div class="system-grid">'+d.items.map(x=>`<button class="system-card" data-system="${esc(x.system)}"><span class="system-formula">${x.system.split(' / ').map(k=>`<span class="chem${components.includes(k)?' hit':''}">${chem(k)}</span>`).join('<span class="muted">·</span>')}</span><span class="card-bottom"><span><b class="card-count">${fmt(x.n)}</b> 条材料</span><span>${fmt(x.records)} 条来源记录 <b class="arrow">↗</b></span></span></button>`).join('')+'</div>';
else $('results').innerHTML=`<div class="tablewrap"><table><thead><tr><th>材料与主要组分</th><th>关键性质</th><th></th></tr></thead><tbody>${d.items.map(recipeRow).join('')}</tbody></table></div>`;
$('page').textContent=`${total?Math.floor(offset/limit)+1:0} / ${Math.ceil(total/limit)} 页`;$('prev').disabled=!offset;$('next').disabled=offset+limit>=total;if($('backSystems'))$('backSystems').onclick=()=>setView('systems',true);
}catch(e){if(n===seq){error(e);$('results').style.opacity='1';$('found').textContent='查询未完成，请调整条件后重试'}}}
function setView(v,clearSystem=false){view=v;if(clearSystem)system='';offset=0;search()}
function storePoints(items){for(const p of items)points.set(Number(p.id),p)}
function val(p){if(p.kind==='玻璃形成结果')return p.value===1?'形成玻璃':'未形成玻璃';return p.value==null?esc(p.raw_value):fmt(p.value)}
function conditionButton(p){return `<button class="condition-link" data-point="${p.id}">条件 ↗</button>`}
function simpleCondition(p){const c=p.conditions||{};let a=[];const temp=p.temp??c['温度°C'],freq=p.freq??c['频率Hz'];if(temp!=null)a.push(fmt(temp)+' °C');if(freq!=null){let scale=freq>=1e9?[1e9,'GHz']:freq>=1e6?[1e6,'MHz']:freq>=1e3?[1e3,'kHz']:[1,'Hz'];a.push(fmt(freq/scale[0])+' '+scale[1])}return a.length?a.join(' · '):'温度 / 频率未注明'}
function showCondition(id){const p=points.get(Number(id));if(!p)return;const rows=[['数据类型',originName(p.origin)],['来源',sourceName(p.source)],['原表与样品',`${p.table_id} / ${p.glass_no}`],['原始数值',p.raw_value],['原始单位',p.raw_unit||'未提供'],['原始标签',p.label],...Object.entries(p.conditions||{})];$('conditionContent').innerHTML=`<div class="condition-lead"><h3>${esc(p.kind)}</h3><div class="property-value">${val(p)} <small>${esc(unitText(p.unit))}</small></div><p class="hint">${esc(simpleCondition(p))}</p></div>${rows.map(([k,v])=>`<div class="condition-definition"><span>${esc(k)}</span><span>${esc(typeof v==='object'?JSON.stringify(v,null,2):v??'未提供')}</span></div>`).join('')}<p class="detail-note" style="margin-top:16px">${p.filterable?'已明确单位的数值可用于筛选。':'此项保留原值，单位或换算尚不完整，不用于跨来源数值筛选。'}${p.origin==='性质汇总'?' 该值来自数据库汇总，可能包含换算或插值。':''}</p><p style="margin-top:12px"><a href="/api/glass/entry/${p.entry_id}/original">下载对应原始资料 ↓</a></p>`;$('conditionModal').showModal()}
function propertyTable(items){storePoints(items);return items.length?`<div class="tablewrap"><table class="property-table"><thead><tr><th>性质</th><th>数值与单位</th><th>测试条件</th><th>数据来源</th><th></th></tr></thead><tbody>${items.map(p=>`<tr><td>${esc(p.kind)}</td><td><strong>${val(p)}</strong><br><span class="hint">${esc(unitText(p.unit))}</span></td><td>${esc(simpleCondition(p))}</td><td><span class="pill neutral">${esc(originName(p.origin))}</span><br><span class="hint">${esc(sourceName(p.source))}</span></td><td>${conditionButton(p)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="missing">未提供符合该筛选条件的性质。</p>'}
function href(s){try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return''}}
function entryHTML(e){const m=e.metadata,refs=m.references||[],year=m.YEAR||m.year,authors=m.AUTHOR||m.authors||'';return `<div class="reference-card"><span class="pill">${esc(sourceName(e.source))}</span><p><b>样品 ${esc(e.glass_no)}</b> <span class="hint">${esc(year||'年份未注明')}</span></p>${authors?`<p>${esc(authors)}</p>`:''}${refs.map(r=>`<p>${esc(r.Title||r.Descr||'')}<br><span class="hint">${esc(r.Authors||'')} ${esc(r.YEAR||'')}</span>${r.DOI?`<br><a href="https://doi.org/${encodeURIComponent(r.DOI)}" target="_blank" rel="noopener noreferrer">DOI ${esc(r.DOI)} ↗</a>`:''}</p>`).join('')}<a href="/api/glass/entry/${e.id}/original">下载原始资料 ↓</a>${href(m.url||m.legacy_source_url)?`　<a href="${esc(href(m.url||m.legacy_source_url))}" target="_blank" rel="noopener noreferrer">来源网页 ↗</a>`:''}<details><summary>原始组成与更多说明</summary><p>${esc(basisName(e.unit))}</p><pre>${esc(JSON.stringify(e.composition,null,2))}</pre>${m.raw_fields?`<div class="tablewrap"><table>${m.raw_fields.filter(x=>x['值']!==null&&x['值']!=='').map(x=>`<tr><td>${esc(x['原标签'])}<br><small>${esc(x['分组原文'])}</small></td><td>${esc(x['值'])}</td></tr>`).join('')}</table></div>`:''}<div class="source-notes">${esc(m.notes||m.legacy_notes||m.quality_note||'')}</div></details></div>`}
async function detail(id){const n=++detailSeq;try{const r=await get('/api/glass/recipe/'+id);if(n!==detailSeq)return;current=r;propOffset=0;points=new Map();for(const g of r.basic)storePoints(g.items);storePoints(r.properties.items);const entries=Object.entries(r.comp).filter(([k,v])=>v!==null&&v!==''&&v!=='-'&&Number(v)!==0).sort((a,b)=>(Number(b[1])||0)-(Number(a[1])||0)),sum=entries.reduce((a,[k,v])=>a+(Number(v)||0),0),max=Math.max(1,...entries.map(([k,v])=>Number(v)||0));$('detailTitle').textContent=r.family==='厂商产品'?r.name:'材料 M'+r.id+' · '+r.family;
$('detail').innerHTML=`<div class="detail-topline"><span class="pill">${esc(r.family)}</span><span class="pill neutral">${esc(basisName(r.basis))}</span>${(r.sources||[]).map(s=>`<span class="pill neutral">${esc(sourceName(s.source))}${s.n>1?' · '+fmt(s.n):''}</span>`).join('')}<span class="hint">${fmt(r.record_count)} 条来源记录 · ${fmt(r.property_count)} 项性质记录</span><button class="text" id="addCompare">${selected.has(r.id)?'已加入对比 ✓':'加入配方对比 +'}</button><a class="hint" href="/api/glass/recipe/${r.id}/export">导出全部性质 ↓</a></div><div class="detail-overview"><section><h3 class="section-title">组成配方</h3><div class="composition-box">${entries.length?`<div class="composition-stack">${entries.map(([k,v],i)=>`<i title="${esc(k)} ${esc(formatAmount(v))}" style="width:${sum?(Number(v)||0)/sum*100:0}%;background:${['#14878c','#52a5ac','#87bdc4','#a9cdd3','#d5e5e8','#cba35d','#ebcd96'][i%7]}"></i>`).join('')}</div>${entries.map(([k,v])=>`<div class="comp-row${highlightNames().has(k)?' hit':''}"><span>${chem(k)}</span><div class="bar"><i style="width:${Math.max(0,Math.min(100,(Number(v)||0)/max*100))}%"></i></div><b>${esc(formatAmount(v))}${basisShort(r.basis)?`<small> ${esc(basisShort(r.basis))}</small>`:''}</b></div>`).join('')}<p>${esc(basisName(r.basis))}。${entries.some(([k,v])=>Number.isFinite(Number(v)))?`合计 ${fmt(entries.reduce((a,[k,v])=>a+(Number(v)||0),0))}${basisShort(r.basis)?' '+basisShort(r.basis):''}${Math.abs(entries.reduce((a,[k,v])=>a+(Number(v)||0),0)-100)<1.5?'。':'（按库内口径累计，不一定恰好为100）。'}`:''}数值按数据库所载口径展示，空缺组分在来源中可能另有记录。</p>`:`<div class="missing">${r.family==='厂商产品'?'厂家未公开完整组分比例':r.basis==='分子式'?'此条目按分子身份记录，详见原始文献信息':'完整配比未提供'}</div><p>${esc(r.name||'未提供名称')}</p>`}</div><p class="detail-note" style="margin-top:15px">不同文献、温度或频率下的性质分别列出。每个数值可查看条件与出处。</p>${r.optical.length?`<div class="optical-list"><p class="hint">另有 ${r.optical.length} 组光谱或色散资料，可在此预览：</p>${r.optical.map(o=>`<button type="button" class="secondary optical-open" data-optical="${o.id}">${esc(opticalName(o.source_path))} ↗</button>`).join('')}</div>`:''}</section><section><h3 class="section-title">基本理化性质 <span class="hint">每项展示最多3条，可向下查看全部</span></h3><div class="basic-grid">${r.basic.map(g=>`<div class="basic-card"><h4>${esc(g.kind)}</h4>${g.items.length?g.items.map(p=>`<div class="value-row"><div><span class="property-value">${val(p)}<small>${esc(unitText(p.unit))}</small></span><span class="origin">${esc(originName(p.origin))} · ${esc(simpleCondition(p))}</span></div>${conditionButton(p)}</div>`).join(''):'<div class="missing">未提供</div>'}</div>`).join('')}</div></section></div><section class="detail-section"><h3 class="section-title">全部性质与测试条件</h3><div class="detail-tools"><div><select id="detailKind" aria-label="筛选当前材料性质"><option value="">全部性质</option>${r.kinds.map(x=>`<option value="${esc(x.kind)}">${esc(x.kind)}（${fmt(x.n)}）</option>`).join('')}</select><select id="detailOrigin" aria-label="筛选当前材料数据类型"><option value="">全部数据类型</option>${['原表解析','原始实验表','文献实验','厂商目录','性质汇总'].map(x=>`<option value="${x}">${originName(x)}</option>`).join('')}</select></div><span class="hint" id="propertyFound"></span></div><div id="propertyRows">${propertyTable(r.properties.items)}</div><div class="pager"><button class="secondary" id="propPrev">← 上一页</button><span id="propertyPage"></span><button class="secondary" id="propNext">下一页 →</button></div></section><section class="detail-section"><h3 class="section-title">文献与原始资料</h3><p class="hint" style="margin-bottom:15px">${r.record_count>40?'当前列出前40条来源；每条性质均可下载其对应原始资料。':'相同组成的来源合并展示，各次测量分别保留。'}</p><div class="references">${r.entries.map(entryHTML).join('')}</div></section>`;
updatePropertyPager(r.properties);$('detailKind').onchange=$('detailOrigin').onchange=()=>{propOffset=0;loadProperties()};$('propPrev').onclick=()=>{propOffset=Math.max(0,propOffset-40);loadProperties()};$('propNext').onclick=()=>{propOffset+=40;loadProperties()};$('addCompare').onclick=()=>{if(selected.size>=4&&!selected.has(r.id)){showModal('配方对比','<p>最多对比4条材料，请先清空已有选择。</p>');return}selected.set(r.id,r);comparebar();$('addCompare').textContent='已加入对比 ✓'};$('recipeModal').showModal();$('recipeModal').scrollTop=0;
}catch(e){error(e)}}
function updatePropertyPager(r){$('propertyFound').textContent=`${fmt(r.total)} 条记录`;$('propertyPage').textContent=`${r.total?Math.floor(r.offset/40)+1:0} / ${Math.ceil(r.total/40)} 页`;$('propPrev').disabled=r.offset===0;$('propNext').disabled=r.offset+40>=r.total}
async function loadProperties(){const n=++propertySeq,mid=current.id;try{const r=await get(`/api/glass/recipe/${mid}/properties?`+new URLSearchParams({kind:$('detailKind').value,origin:$('detailOrigin').value,offset:propOffset,limit:40}));if(n!==propertySeq||mid!==current.id)return;$('propertyRows').innerHTML=propertyTable(r.items);updatePropertyPager(r)}catch(e){error(e)}}
function showModal(title,html){$('modalTitle').textContent=title;$('modalContent').innerHTML=html;$('modal').showModal()}
function apply(){if(($('lo').value!==''||$('hi').value!=='')&&!$('kind').value){error('请先选择一种性质及其单位');return}if($('lo').value!==''&&$('hi').value!==''&&Number($('lo').value)>Number($('hi').value)){error('最小值不能大于最大值');return}system='';offset=0;view=$('family').value==='厂商产品'||$('query').value.trim()||(typeof intentFilters!=='undefined'&&intentFilters.length)?'recipes':'systems';search()}
$('apply').onclick=apply;$('query').onkeydown=e=>{if(e.key==='Enter')apply()};$('component').onchange=e=>{add(e.target.value);e.target.value=''};$('chips').onclick=e=>{const b=e.target.closest('[data-chip]');if(b){components.splice(Number(b.dataset.chip),1);chips()}};
$('results').onclick=e=>{const point=e.target.closest('[data-point]');if(point){showCondition(point.dataset.point);return}const s=e.target.closest('[data-system]'),r=e.target.closest('[data-rid]');if(s){system=s.dataset.system;view='recipes';offset=0;search()}else if(r)detail(Number(r.dataset.rid))};
if($('sortBy'))$('sortBy').onchange=()=>{readSort();offset=0;if(view!=='systems')search()};
$('all').onclick=()=>setView('systems',true);$('listView').onclick=()=>setView('recipes');$('prev').onclick=()=>{offset=Math.max(0,offset-limit);search()};$('next').onclick=()=>{offset+=limit;search()};$('reset').onclick=()=>{components=[];chips();for(const k of ['query','lo','hi','kind','family','source'])$(k).value='';$('match').value='contains';$('pcb').checked=false;system='';view='systems';offset=0;search()};$('export').onclick=()=>{location.href='/api/glass/export?'+params()};$('clear').onclick=()=>{selected.clear();comparebar()};
$('closeRecipe').onclick=()=>$('recipeModal').close();$('closeCondition').onclick=()=>$('conditionModal').close();$('close').onclick=()=>$('modal').close();$('recipeModal').onclick=e=>{const o=e.target.closest('[data-optical]');if(o){showOptical(o.dataset.optical);return}const b=e.target.closest('[data-point]');if(b)showCondition(b.dataset.point)};
$('compare').onclick=()=>{const rs=[...selected.values()],keys=[...new Set(rs.flatMap(r=>Object.keys(r.comp)))].sort();rs.forEach(r=>r.basic.forEach(g=>storePoints(g.items)));let html='<p class="hint" style="margin-bottom:18px">组成口径和测试条件不同的数值，请分别解读。以下每个性质数值都保留自己的单位和条件。</p><div class="tablewrap"><table><thead><tr><th>项目</th>'+rs.map(r=>`<th>M${r.id}<br>${esc(r.name.slice(0,60))}</th>`).join('')+'</tr></thead><tbody><tr><td>口径</td>'+rs.map(r=>`<td>${esc(basisName(r.basis))}</td>`).join('')+'</tr>'+keys.map(k=>`<tr><td>${chem(k)}</td>${rs.map(r=>`<td>${r.comp[k]==null||r.comp[k]===''?'<span class="missing">未提供</span>':esc(formatAmount(r.comp[k]))+(basisShort(r.basis)?' '+esc(basisShort(r.basis)):'')}</td>`).join('')}</tr>`).join('');for(const kind of ['密度','玻璃转变温度','杨氏模量','显微硬度','线膨胀系数','相对介电常数','介电损耗角正切'])html+=`<tr><td>${kind}</td>${rs.map(r=>{const p=r.basic.find(g=>g.kind===kind)?.items[0];return `<td>${p?val(p)+' '+esc(unitText(p.unit))+'<br>'+conditionButton(p):'未提供'}</td>`}).join('')}</tr>`;showModal('材料配方与性质对比',html+'</tbody></table></div>')};$('modalContent').onclick=e=>{const b=e.target.closest('[data-point]');if(b)showCondition(b.dataset.point)};
$('kind').onchange=()=>{$('unitHint').textContent=$('kind').value?'筛选单位：'+unitText(JSON.parse($('kind').value)[1])+'。具体测试条件见每条数据。':'选择性质后可按对应单位筛选。'};
$('family').onchange=()=>{if($('family').value==='厂商产品'){view='recipes';system='';offset=0;search()}};
(async()=>{try{summary=await get('/api/glass/summary');$('stats').innerHTML=[['去重材料条目',summary.materials],['来源记录',summary.source_records],['性质记录',summary.properties],['数据来源',summary.sources.length]].map(([name,n])=>`<div><strong>${fmt(n)}</strong><span>${name}</span></div>`).join('');$('component').innerHTML+=[...summary.components].sort((a,b)=>a.name.localeCompare(b.name)).map(x=>`<option value="${esc(x.name)}">${esc(x.name)}（${fmt(x.n)}）</option>`).join('');$('family').innerHTML+=summary.families.map(x=>`<option value="${esc(x.family)}">${esc(x.family)}（${fmt(x.n)}）</option>`).join('');$('source').innerHTML+=summary.sources.map(x=>`<option value="${esc(x.source)}">${esc(sourceName(x.source))}</option>`).join('');const kinds=summary.property_kinds.filter(x=>x.filterable&&x.n>0);$('kind').innerHTML+=kinds.map(x=>`<option value="${esc(JSON.stringify([x.kind,x.unit]))}">${esc(x.kind)} · ${esc(unitText(x.unit))}</option>`).join('');$('quick').innerHTML=['SiO2','B2O3','Al2O3','MgO','CaO','Na2O'].map(k=>`<button data-add="${k}">${chem(k)} +</button>`).join('');$('quick').onclick=e=>{const b=e.target.closest('[data-add]');if(b)add(b.dataset.add)};window.dispatchEvent(new Event('catalog-ready'))}catch(e){error(e)}})();
if(!location.hash)location.hash='home';
